SELECT @{pipeline().parameters.SourceColumns} 
FROM @{pipeline().parameters.SourceTableName} 
WHERE @{pipeline().parameters.DateColumnName} 
BETWEEN '@{pipeline().parameters.StartDate}' AND '@{pipeline().parameters.EndDate}' 
AND @{pipeline().parameters.PartitionField} = '@{item()[pipeline().parameters.PartitionField]}'

SELECT DISTINCT @{pipeline().parameters.PartitionField}
FROM @{pipeline().parameters.SourceTableName}
WHERE @{pipeline().parameters.DateColumnName} 
BETWEEN '@{pipeline().parameters.StartDate}' AND '@{pipeline().parameters.EndDate}'

SELECT DISTINCT @{pipeline().parameters.PartitionField}
FROM @{pipeline().parameters.SourceTableName}
WHERE 
@{pipeline().parameters.DateColumnName} BETWEEN '@{pipeline().parameters.StartDate}' AND '@{pipeline().parameters.EndDate}'
